export interface ScreenReelFlowPlayback { modes?: ScreenReelMode[]; default?: ScreenReelMode | 'ask'; video?: ScreenReelPlaybackSettings; autoplay?: ScreenReelPlaybackSettings; guided?: ScreenReelPlaybackSettings }
export interface ScreenReelMountPlayback extends ScreenReelFlowPlayback { force?: ScreenReelMode | 'ask'; remember?: boolean | 'preselect' | 'skip' }
export interface ScreenReelFlow { id: string; name: string; defaults?: { playback?: ScreenReelFlowPlayback; /** @deprecated use playback.default */ advance?: ScreenReelMode | 'ask' | 'auto'; dwellMs?: number; settleMs?: number; [key: string]: unknown }; variables?: Record<string, string | { label?: string; default?: string }>; scenes: ScreenReelScene[] }
export interface ScreenReelScene { id: string; enabled?: boolean; route: string; title?: string; talkingPoints?: string; narration?: string; waitFor?: string; timeoutMs?: number; settleMs?: number; dwellMs?: number; narrationCapMs?: number; advance?: ScreenReelMode | 'auto'; cleanup?: ScreenReelAction[]; leadInMs?: number; tailMs?: number; endsInNavigation?: boolean; actions: ScreenReelAction[] }
export interface ScreenReelAction { id?: string; type: 'callout' | 'highlight' | 'glow' | 'spotlight' | 'flash' | 'reel' | 'reveal' | 'snippet' | 'countdown' | 'click' | 'hover' | 'focus' | 'type' | 'set' | 'toggle' | 'lever' | 'drag' | 'scrollIntoView' | 'scroll' | 'wait' | 'waitFor' | 'goto' | 'choice' | 'pointer' | 'call' | 'fill'; selector?: string; index?: number; afterMs?: number; narration?: string; stepMs?: number; atMs?: number; narrationAudio?: string; pace?: { field: 'holdMs' | 'ms' | 'afterMs'; addedMs: number }; fingerprint?: { text?: string; tag?: string; role?: string }; [key: string]: unknown }
export interface ScreenReelRouter { getRoute(): string; navigate(route: string): void | Promise<void>; subscribe?(listener: () => void): () => void }
export interface ScreenReelLegacyStorage { id?: string; flowsKey?: string; activeFlowKey?: string; notesVisibleKey?: string; enabledKey?: string; session?: { positionKey?: string; playingKey?: string; navigationKey?: string } }
export interface ScreenReelValidationAction { actionIndex: number; actionId?: string; type: string; selector?: string; errors: string[] }
export interface ScreenReelValidationReport { ok: boolean; flowId: string; sceneId: string | null; route: string | null; sceneErrors: string[]; actions: ScreenReelValidationAction[] }
export interface ScreenReelOptions { projectId: string; flow: { src: string } | { data: ScreenReelManifest }; assetBase?: string; activationQueryParam?: string; notesMode?: 'reserve' | 'overlay'; loop?: boolean; strict?: boolean; cursorMotion?: 'arc' | 'line'; routesEqual?: (currentRoute: string, sceneRoute: string) => boolean; router?: ScreenReelRouter; legacyStorage?: ScreenReelLegacyStorage; variables?: Record<string, string>; pages?: string[]; narration?: boolean | { rate?: number; voiceName?: string; lang?: string; speech?: boolean }; playback?: ScreenReelMountPlayback; /** @deprecated use playback.force */ advance?: ScreenReelMode | 'auto' | 'ask'; dim?: number | false; /** @deprecated use playback.force: 'ask' */ chooser?: boolean; /** @deprecated use playback.<mode>.controls */ controls?: ScreenReelControl[] | { guided?: ScreenReelControl[]; auto?: ScreenReelControl[]; autoplay?: ScreenReelControl[]; video?: ScreenReelControl[] }; studio?: boolean; position?: 'right' | 'center'; shield?: boolean; disableOnComplete?: boolean; restoreOnExit?: boolean; functions?: Record<string, (...args: unknown[]) => unknown>; labels?: Partial<ScreenReelLabels>; analytics?: { onEvent?: (event: ScreenReelAnalyticsEvent) => void; beaconUrl?: string } }
export interface ScreenReelAnalyticsEvent { event: string; ts: number; sessionId: string; projectId: string; flowId: string; sceneId: string | null; sceneIndex: number; sceneCount: number; percentComplete: number; share: boolean }
export type ScreenReelControl = 'flow' | 'count' | 'prev' | 'play' | 'next' | 'sound' | 'notes' | 'studio' | 'exit'
export interface ScreenReelLabels { back: string; next: string; finish: string; skip: string; close: string; stepOf(step: number, total: number): string; chooserHint: string; guided: string; guidedHint: string; autoplay: string; autoplayHint: string; video: string; videoHint: string; previousScene: string; nextScene: string; nextStep: string; play: string; pause: string; exit: string; sceneOf(scene: number, total: number): string; startHint(mode: string, scenes: number): string; finished: string; endHint(scenes: number): string; replay: string }
export interface ScreenReelProjector { start(flowId: string, options?: { position?: number; mode?: ScreenReelMode | 'ask' | 'auto' }): Promise<this>; enable(): this; disable(reason?: 'user' | 'complete' | 'api'): this; play(): Promise<void>; pause(): this; validateScene(sceneId?: string): ScreenReelValidationReport; openStudio(options?: Record<string, unknown>): Promise<unknown>; captureCurrent(): void; destroy(): void }
export interface ScreenReelApi { mount(target: Element, options: ScreenReelOptions): Promise<ScreenReelProjector>; openStudio(options?: Record<string, unknown>): Promise<unknown>; registerFn(name: string, fn: (...args: unknown[]) => unknown): () => void; unregisterFn(name: string, fn?: (...args: unknown[]) => unknown): void; validateScene(sceneId?: string): ScreenReelValidationReport }
declare global { interface Window { ScreenReel: ScreenReelApi & { ready: Promise<ScreenReelApi> } } }
